"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["60234"],{55659(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.item_formulario.restricao_incoerente","status":422,"titulo":"A restri\xe7\xe3o de valor n\xe3o se aplica ao tipo do campo"},"descricao":{"codigo":"uniplus.item_formulario.restricao_incoerente","requisitos":["UNI-REQ-0145"],"oQueAconteceu":["Cada campo declara as restri\xe7\xf5es de valor e as op\xe7\xf5es que oferece (UNI-REQ-0145), e cada restri\xe7\xe3o s\xf3 cabe em um tipo de campo. Uma restri\xe7\xe3o de `restricoes` do item n\xe3o cabe no `tipoDeCampo` dele:","| Restri\xe7\xe3o | Tipo de campo |\\n| --- | --- |\\n| `FAIXA_NUMERICA` | `NUMERO` |\\n| `TAMANHO_TEXTO` | `TEXTO` |\\n| `OPCOES_PERMITIDAS` e `OPCOES_DAS_RESPOSTAS` | `ESCOLHA_UNICA` e `ESCOLHA_MULTIPLA` |\\n| `MUNICIPIOS_DA_UF` | `MUNICIPIO` |\\n| `FAIXA_DE_DATA` | `DATA` |","A mensagem \xe9 \\"A faixa num\xe9rica s\xf3 se aplica ao campo num\xe9rico, o tamanho s\xf3 ao de texto, as op\xe7\xf5es s\xf3 ao de sele\xe7\xe3o, os munic\xedpios da UF s\xf3 ao de munic\xedpio e a faixa de data s\xf3 ao de data.\\" A recusa vem na lista `errors`, com `field` igual a `itens[i].restricoes[k]` ou `grupos[g].subitens[j].restricoes[k]`; nos modelos de formul\xe1rio come\xe7a por `conteudo.`. H\xe1 uma entrada por restri\xe7\xe3o que n\xe3o cabe, junto das demais recusas da forma do item, e nada \xe9 gravado. A sem\xe2ntica de cada restri\xe7\xe3o contra o cat\xe1logo s\xf3 \xe9 conferida para a que cabe no tipo do campo.","Na grava\xe7\xe3o dos itens do formul\xe1rio, esta recusa s\xf3 sai para o item cujo fato existe, \xe9 colet\xe1vel e combina com o tipo de campo: o item com fato [desconhecido](/erros/uniplus.item_formulario.fato_desconhecido), [n\xe3o colet\xe1vel](/erros/uniplus.item_formulario.fato_nao_coletavel) ou com tipo de campo [incoerente](/erros/uniplus.item_formulario.tipo_de_campo_incoerente_com_dominio) \xe9 recusado por essa causa, e o resto da forma dele s\xf3 \xe9 conferido depois que ela for corrigida. Nos modelos, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Retire a restri\xe7\xe3o que n\xe3o cabe, ou troque o tipo de campo do item por um que a aceite, desde que o tipo combine com o fato."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Item formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);